}

/** The public job shape returned by the API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** The fields the worker needs after claiming an attempt. `attempts` is already incremented. */
export interface ClaimedJob {
  seq: number;
  attempts: number;
  input: string;
  steps: number;
  failAttempts: number;
}

export type CreateOutcome = { kind: 'created'; job: Job } | { kind: 'replayed'; job: Job } | { kind: 'conflict' };

interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  not_before: number;
  created_at: string;
  updated_at: string;
}

/** A worker whose heartbeat is older than this is reported as down. */
export const HEARTBEAT_FRESH_MS = 3000;

const iso = (ms: number): string => new Date(ms).toISOString();

/** Canonical form of a payload after defaults, used to compare idempotent replays. */
const fingerprint = (spec: JobSpec): string => JSON.stringify([spec.input, spec.steps, spec.failAttempts]);

function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** All job reads and writes. Both the server and the worker use this, so SQL lives in one place. */
export class JobStore {
  private readonly db: DatabaseSync;
  private readonly insertJob: StatementSync;
  private readonly selectJobById: StatementSync;
  private readonly selectAllJobs: StatementSync;
  private readonly selectIdempotency: StatementSync;
  private readonly insertIdempotency: StatementSync;
  private readonly selectNextQueued: StatementSync;
  private readonly claimJob: StatementSync;
  private readonly setProgress: StatementSync;
  private readonly completeJob: StatementSync;
  private readonly failJob: StatementSync;
  private readonly retryJob: StatementSync;
  private readonly requeueJob: StatementSync;
  private readonly requeueRunning: StatementSync;
  private readonly upsertHeartbeat: StatementSync;
  private readonly deleteHeartbeat: StatementSync;
  private readonly selectHeartbeat: StatementSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.insertJob = db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, not_before, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
    );
    this.selectJobById = db.prepare('SELECT * FROM jobs WHERE id = ?');
    this.selectAllJobs = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
    this.selectIdempotency = db.prepare('SELECT fingerprint, job_id FROM idempotency_keys WHERE key = ?');
    this.insertIdempotency = db.prepare('INSERT INTO idempotency_keys (key, fingerprint, job_id) VALUES (?, ?, ?)');
    this.selectNextQueued = db.prepare(
      "SELECT * FROM jobs WHERE status = 'queued' AND not_before <= ? ORDER BY seq LIMIT 1",
    );
    this.claimJob = db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?",
    );
    this.setProgress = db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?');
    this.completeJob = db.prepare(
      "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?",
    );
    this.failJob = db.prepare(
      "UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, updated_at = ? WHERE seq = ?",
    );
    this.retryJob = db.prepare(
      "UPDATE jobs SET status = 'queued', progress_completed = 0, not_before = ?, updated_at = ? WHERE seq = ?",
    );
    this.requeueJob = db.prepare(
      "UPDATE jobs SET status = 'queued', progress_completed = 0, not_before = 0, updated_at = ? WHERE seq = ?",
    );
    this.requeueRunning = db.prepare(
      "UPDATE jobs SET status = 'queued', progress_completed = 0, not_before = 0, updated_at = ? WHERE status = 'running'",
    );
    this.upsertHeartbeat = db.prepare(
      'INSERT INTO worker_heartbeat (id, seen_at) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET seen_at = excluded.seen_at',
    );
    this.deleteHeartbeat = db.prepare('DELETE FROM worker_heartbeat');
    this.selectHeartbeat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1');
  }

  /**
   * Creates a job, or replays/conflicts with an earlier job that used the same idempotency key.
   * The key check and the insert share one transaction, so a key can never create two jobs.
   */
  createJob(spec: JobSpec, idempotencyKey: string | undefined, now: number = Date.now()): CreateOutcome {
    return transaction(this.db, () => {
      const fp = fingerprint(spec);
      if (idempotencyKey !== undefined) {
        const existing = this.selectIdempotency.get(idempotencyKey) as { fingerprint: string; job_id: string } | undefined;
        if (existing) {
          if (existing.fingerprint !== fp) return { kind: 'conflict' };
          const job = this.getJob(existing.job_id);
          if (job) return { kind: 'replayed', job };
        }
      }
      const id = randomUUID();
      const ts = iso(now);
      this.insertJob.run(id, spec.input, spec.steps, spec.failAttempts, ts, ts);
      if (idempotencyKey !== undefined) this.insertIdempotency.run(idempotencyKey, fp, id);
      const job = this.getJob(id);
      if (!job) throw new Error(`job ${id} missing after insert`);
      return { kind: 'created', job };
    });
  }

  getJob(id: string): Job | undefined {
    const row = this.selectJobById.get(id) as JobRow | undefined;
    return row ? toJob(row) : undefined;
  }

  listJobs(): Job[] {
    return (this.selectAllJobs.all() as unknown as JobRow[]).map(toJob);
  }

  /** Claims the oldest queued job that is due, marking it running with one more attempt. */
  claimNext(now: number = Date.now()): ClaimedJob | undefined {
    return transaction(this.db, () => {
      const row = this.selectNextQueued.get(now) as JobRow | undefined;
      if (!row) return undefined;
      this.claimJob.run(iso(now), row.seq);
      return { seq: row.seq, attempts: row.attempts + 1, input: row.input, steps: row.steps, failAttempts: row.fail_attempts };
    });
  }

  recordProgress(seq: number, completed: number, now: number = Date.now()): void {
    this.setProgress.run(completed, iso(now), seq);
  }

  complete(seq: number, output: string, now: number = Date.now()): void {
    this.completeJob.run(output, iso(now), seq);
  }

  fail(seq: number, error: string, now: number = Date.now()): void {
    this.failJob.run(error, iso(now), seq);
  }

  /** Puts a failed attempt back in the queue, due at `notBefore` (epoch ms). */
  scheduleRetry(seq: number, notBefore: number, now: number = Date.now()): void {
    this.retryJob.run(notBefore, iso(now), seq);
  }

  /** Returns an interrupted attempt to the queue so it is processed again. */
  requeue(seq: number, now: number = Date.now()): void {
    this.requeueJob.run(iso(now), seq);
  }

  /** Requeues every job left `running` by a worker that stopped without finishing it. Returns how many. */
  requeueInterrupted(now: number = Date.now()): number {
    return Number(this.requeueRunning.run(iso(now)).changes);
  }

  writeHeartbeat(now: number = Date.now()): void {
    this.upsertHeartbeat.run(now);
  }

  clearHeartbeat(): void {
    this.deleteHeartbeat.run();
  }

  /** True if the worker has written a heartbeat within the last HEARTBEAT_FRESH_MS. */
  workerIsUp(now: number = Date.now()): boolean {
    const row = this.selectHeartbeat.get() as { seen_at: number } | undefined;
    return row !== undefined && now - Number(row.seen_at) < HEARTBEAT_FRESH_MS;
  }
}

