import type { JobSpec } from './store.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type Validation = { ok: true; value: JobSpec } | { ok: false; fields: FieldError[] };

export const MAX_INPUT_LENGTH = 1000;
export const MIN_STEPS = 1;
export const MAX_STEPS = 20;
export const DEFAULT_STEPS = 5;
export const MAX_FAIL_ATTEMPTS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = ['input', 'steps', 'failAttempts'];

function integerField(
  body: Record<string, unknown>,
  name: string,
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number | undefined {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  if (value < min || value > max) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return value;
}

/** Validates a parsed request body. Returns every offending field, not just the first. */
export function validateJobBody(body: unknown): Validation {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'must be a JSON object' }] };
  }
  const record = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(record)) {
    if (!ALLOWED_FIELDS.includes(key)) fields.push({ field: key, message: 'is not a recognised field' });
  }

  let input: string | undefined;
  const raw = record.input;
  if (raw === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof raw !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (raw.length < 1 || raw.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (raw.trim() === '') {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = raw;
  }

  const steps = integerField(record, 'steps', MIN_STEPS, MAX_STEPS, DEFAULT_STEPS, fields);
  const failAttempts = integerField(record, 'failAttempts', 0, MAX_FAIL_ATTEMPTS, DEFAULT_FAIL_ATTEMPTS, fields);

  if (fields.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) {
    return { ok: false, fields };
  }
  return { ok: true, value: { input, steps, failAttempts } };
}

