import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { JobStore, type Job } from './store.ts';
import { IDEMPOTENCY_KEY_PATTERN, validateJobBody, type FieldError } from './validation.ts';

const MAX_BODY_BYTES = 64 * 1024;

const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

type BodyRead = { kind: 'ok'; text: string } | { kind: 'too-large' } | { kind: 'error' };

function readBody(req: IncomingMessage): Promise<BodyRead> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? { kind: 'too-large' } : { kind: 'ok', text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', () => resolve({ kind: 'error' }));
  });
}

function isJsonContentType(value: string | undefined): boolean {
  return value !== undefined && value.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse, store: JobStore): Promise<void> {
  const body = await readBody(req);
  const fields: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  let idempotencyKey: string | undefined;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY_PATTERN.test(keyHeader)) idempotencyKey = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'must be 1 to 128 letters, digits, "_" or "-"' });
  }

  let bodyError: string | undefined;
  let parsed: unknown;
  if (body.kind === 'too-large') bodyError = `request body must be at most ${MAX_BODY_BYTES} bytes`;
  else if (body.kind === 'error') bodyError = 'request body could not be read';
  else if (!isJsonContentType(req.headers['content-type'])) bodyError = 'Content-Type must be application/json';
  else {
    try {
      parsed = JSON.parse(body.text);
    } catch {
      bodyError = 'request body is not valid JSON';
    }
  }

  if (bodyError !== undefined) {
    fields.unshift({ field: 'body', message: bodyError });
  } else {
    const validation = validateJobBody(parsed);
    if (!validation.ok) fields.unshift(...validation.fields);
    else if (fields.length === 0) {
      const outcome = store.createJob(validation.value, idempotencyKey);
      if (outcome.kind === 'conflict') {
        sendError(res, 409, 'idempotency_conflict', 'this Idempotency-Key was already used with a different payload');
      } else {
        sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
      }
      return;
    }
  }

  sendError(res, 400, 'invalid_request', 'the submission is invalid', fields);
}

async function handle(req: IncomingMessage, res: ServerResponse, store: JobStore): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  let allowed: string[] | undefined;
  let jobId: string | undefined;
  if (pathname === '/health' || pathname === '/') allowed = ['GET'];
  else if (pathname === '/api/jobs') allowed = ['GET', 'POST'];
  else {
    const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
    if (match) {
      allowed = ['GET'];
      jobId = match[1];
    }
  }

  if (!allowed) return sendError(res, 404, 'not_found', `no route for ${pathname}`);
  if (!allowed.includes(method)) {
    res.setHeader('allow', allowed.join(', '));
    return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${pathname}`);
  }

  if (pathname === '/health') {
    return sendJson(res, 200, { status: 'ok', worker: store.workerIsUp() ? 'up' : 'down' });
  }
  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (jobId === undefined) {
    if (method === 'POST') return handleCreateJob(req, res, store);
    return sendJson(res, 200, { jobs: store.listJobs() satisfies Job[] });
  }
  const job = store.getJob(jobId);
  if (!job) return sendError(res, 404, 'not_found', `no job with id ${jobId}`);
  return sendJson(res, 200, job);
}

const db = openDatabase();
const store = new JobStore(db);

const server = createServer((req, res) => {
  handle(req, res, store).catch((error: unknown) => {
    console.error('request failed:', error);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'unexpected server error');
  });
});

const port = process.env.PORT ? Number(process.env.PORT) : 3000;
server.on('error', (error) => {
  console.error(`server error: ${error.message}`);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

