import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { JobStore, type ClaimedJob } from './store.ts';

/** Time for one processing step. */
const STEP_MS = 100;
/** Delay before a failed attempt is retried. Must be between 250 ms and 2 s. */
const RETRY_DELAY_MS = 500;
/** Total attempts before a job is marked failed. */
const MAX_ATTEMPTS = 3;
/** How often the worker writes its heartbeat. The server reports "down" after 3 s without one. */
const HEARTBEAT_MS = 1000;
/** How long an idle worker waits before looking for queued work again. */
const IDLE_POLL_MS = 200;

const db = openDatabase();
const store = new JobStore(db);
let stopping = false;

// A job left "running" by a worker that died is processed again. This process is the only worker, so
// anything running at startup was orphaned.
const recovered = store.requeueInterrupted();
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
store.writeHeartbeat();
const heartbeat = setInterval(() => store.writeHeartbeat(), HEARTBEAT_MS);

function requestStop(): void {
  stopping = true;
}
process.on('SIGTERM', requestStop);
process.on('SIGINT', requestStop);

/** Runs one attempt of a claimed job, leaving the job in its next persisted state. */
async function runAttempt(job: ClaimedJob): Promise<void> {
  if (job.attempts <= job.failAttempts) {
    // Simulated transient failure: the attempt fails at its first step, before any progress.
    await sleep(STEP_MS);
    if (job.attempts >= MAX_ATTEMPTS) store.fail(job.seq, 'transient failure');
    else store.scheduleRetry(job.seq, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    if (stopping) {
      // Hand the job back so the next worker start processes it again.
      store.requeue(job.seq);
      return;
    }
    await sleep(STEP_MS);
    store.recordProgress(job.seq, step);
  }
  store.complete(job.seq, job.input.toUpperCase());
}

console.log('worker started');
while (!stopping) {
  try {
    const job = store.claimNext();
    if (job) await runAttempt(job);
    else await sleep(IDLE_POLL_MS);
  } catch (error) {
    console.error('worker error:', error);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeat);
store.clearHeartbeat();
db.close();
console.log('worker stopped');

